-- Synthetic EHR-like records for prescription safety testing.
-- These are realistic but fictional de-identified records.

on conflict (patient_code) do nothing;

on conflict (encounter_code) do nothing;

on conflict (condition_code) do nothing;

on conflict (medication_code) do nothing;

on conflict (allergy_code) do nothing;

on conflict (observation_code) do nothing;

on conflict (procedure_code) do nothing;

on conflict (note_code) do nothing;

select id, 'ehr_patients', patient_code, 'create', 'system_seed', now(), 'Synthetic de-identified EHR seed record created for prescription safety prototype'
from ehr_patients
where patient_code between 'EHR-PT-0001' and 'EHR-PT-0020'
  and not exists (
    select 1
    from ehr_audit_events
    where ehr_audit_events.entity_table = 'ehr_patients'
      and ehr_audit_events.entity_code = ehr_patients.patient_code
      and ehr_audit_events.action = 'create'
  );
