insert into ehr_clinical_notes (note_code, patient_id, encounter_id, note_type, note_text, authored_at, note_status) values
  ('NOTE-0001-A', (select id from ehr_patients where patient_code='EHR-PT-0001'), (select id from ehr_encounters where encounter_code='ENC-0001-A'), 'Medication review note', 'Diabetes control remains above target with reduced renal reserve. Avoid nephrotoxic additions where possible. Patient denies recent hypoglycaemia. Continue antiplatelet history review before adding any medicine that increases bleeding risk.', '2026-04-02 09:50+00', 'current'),
  ('NOTE-0002-A', (select id from ehr_patients where patient_code='EHR-PT-0002'), (select id from ehr_encounters where encounter_code='ENC-0002-A'), 'Respiratory review note', 'Increased rescue inhaler use over two weeks. No fever. Penicillin allergy confirmed by prior urticaria. Consider interaction and allergy review before antibiotics for respiratory symptoms.', '2026-04-03 12:00+00', 'current'),
  ('NOTE-0003-A', (select id from ehr_patients where patient_code='EHR-PT-0003'), (select id from ehr_encounters where encounter_code='ENC-0003-A'), 'Cardiology inpatient note', 'Atrial fibrillation treated with rate control and anticoagulation. INR above target on admission. Potassium mildly elevated while taking spironolactone. Avoid interacting antibiotics and NSAIDs unless reviewed.', '2026-04-04 18:20+00', 'current'),
  ('NOTE-0004-A', (select id from ehr_patients where patient_code='EHR-PT-0004'), (select id from ehr_encounters where encounter_code='ENC-0004-A'), 'Infectious diseases note', 'Patient is taking rifampicin-based tuberculosis therapy with dolutegravir-containing ART. Liver enzymes mildly raised. Check for enzyme induction interactions and hepatotoxic combinations before new prescriptions.', '2026-04-05 09:20+00', 'current'),
  ('NOTE-0005-A', (select id from ehr_patients where patient_code='EHR-PT-0005'), (select id from ehr_encounters where encounter_code='ENC-0005-A'), 'Neurology note', 'Seizures controlled on valproate. Mood symptoms treated with sertraline. Counselled about serotonin syndrome symptoms if triptan use increases. Liver function currently acceptable.', '2026-04-06 13:40+00', 'current'),
  ('NOTE-0006-A', (select id from ehr_patients where patient_code='EHR-PT-0006'), (select id from ehr_encounters where encounter_code='ENC-0006-A'), 'Obstetric medicine note', 'Blood pressure remains elevated. Trace protein noted but no severe features documented. Avoid medicines contraindicated in pregnancy and monitor haemoglobin response to iron therapy.', '2026-04-07 10:55+00', 'current'),
  ('NOTE-0007-A', (select id from ehr_patients where patient_code='EHR-PT-0007'), (select id from ehr_encounters where encounter_code='ENC-0007-A'), 'Haematology review note', 'Chronic sickle cell disease with baseline anaemia. Hydroxyurea tolerated. Avoid medicines that worsen sedation when opioid rescue therapy is used.', '2026-04-08 10:25+00', 'current'),
  ('NOTE-0008-A', (select id from ehr_patients where patient_code='EHR-PT-0008'), (select id from ehr_encounters where encounter_code='ENC-0008-A'), 'Emergency respiratory note', 'COPD exacerbation with hypoxia and tachypnoea. Macrolide intolerance to erythromycin recorded. Monitor QT risk if prescribing macrolides or fluoroquinolones.', '2026-04-09 03:30+00', 'current'),
  ('NOTE-0009-A', (select id from ehr_patients where patient_code='EHR-PT-0009'), (select id from ehr_encounters where encounter_code='ENC-0009-A'), 'Gastroenterology note', 'History of peptic ulcer with positive occult blood and anaemia. Avoid oral NSAIDs where possible. If analgesia required, prefer safer alternatives and gastroprotection.', '2026-04-09 12:35+00', 'current'),
  ('NOTE-0010-A', (select id from ehr_patients where patient_code='EHR-PT-0010'), (select id from ehr_encounters where encounter_code='ENC-0010-A'), 'Cardiology follow-up note', 'Post-MI patient on dual antiplatelet therapy and high-intensity statin. Bleeding risk should be reviewed before adding anticoagulants, NSAIDs, or additional antiplatelet agents.', '2026-04-10 09:45+00', 'current'),
  ('NOTE-0011-A', (select id from ehr_patients where patient_code='EHR-PT-0011'), (select id from ehr_encounters where encounter_code='ENC-0011-A'), 'Endocrinology note', 'TSH remains elevated. Patient takes calcium supplement that may reduce levothyroxine absorption if taken together. Reinforced dose separation.', '2026-04-11 09:20+00', 'current'),
  ('NOTE-0012-A', (select id from ehr_patients where patient_code='EHR-PT-0012'), (select id from ehr_encounters where encounter_code='ENC-0012-A'), 'Nephrology note', 'CKD stage 3b with gout. Dose adjustment needed for renally cleared medicines. Colchicine toxicity risk should be checked if macrolides or strong CYP/P-gp inhibitors are prescribed.', '2026-04-12 14:50+00', 'current'),
  ('NOTE-0013-A', (select id from ehr_patients where patient_code='EHR-PT-0013'), (select id from ehr_encounters where encounter_code='ENC-0013-A'), 'Neurology note', 'Migraine frequency remains high. On propranolol and amitriptyline. Monitor blood pressure and additive sedative effects when new medicines are added.', '2026-04-13 11:40+00', 'current'),
  ('NOTE-0014-A', (select id from ehr_patients where patient_code='EHR-PT-0014'), (select id from ehr_encounters where encounter_code='ENC-0014-A'), 'Chest clinic note', 'Continuation phase tuberculosis treatment ongoing. Prior pyrazinamide hepatitis documented. Avoid hepatotoxic additions and check rifampicin interactions.', '2026-04-14 10:40+00', 'current'),
  ('NOTE-0015-A', (select id from ehr_patients where patient_code='EHR-PT-0015'), (select id from ehr_encounters where encounter_code='ENC-0015-A'), 'HIV clinic note', 'Viral load undetectable. Sulfonamide allergy history conflicts with current co-trimoxazole prophylaxis; reaction history should be reassessed and alternatives considered if rash recurs.', '2026-04-15 10:00+00', 'current'),
  ('NOTE-0016-A', (select id from ehr_patients where patient_code='EHR-PT-0016'), (select id from ehr_encounters where encounter_code='ENC-0016-A'), 'Rheumatology note', 'Methotrexate therapy with mild transaminitis and leukopenia. Avoid trimethoprim-containing antibiotics and other myelosuppressive medicines unless specialist reviewed.', '2026-04-16 13:55+00', 'current'),
  ('NOTE-0017-A', (select id from ehr_patients where patient_code='EHR-PT-0017'), (select id from ehr_encounters where encounter_code='ENC-0017-A'), 'Psychiatry note', 'Lithium level within therapeutic range but creatinine is slightly raised. Thiazide therapy may increase lithium exposure. Avoid NSAIDs and ACE inhibitors without lithium monitoring plan.', '2026-04-17 15:45+00', 'current'),
  ('NOTE-0018-A', (select id from ehr_patients where patient_code='EHR-PT-0018'), (select id from ehr_encounters where encounter_code='ENC-0018-A'), 'Anticoagulation note', 'Recent DVT treated with apixaban. Aspirin-related GI bleed history recorded. Avoid NSAIDs and additional anticoagulants unless benefit clearly outweighs bleeding risk.', '2026-04-18 09:10+00', 'current'),
  ('NOTE-0019-A', (select id from ehr_patients where patient_code='EHR-PT-0019'), (select id from ehr_encounters where encounter_code='ENC-0019-A'), 'Transplant clinic note', 'Tacrolimus trough is above target with creatinine rise. Fluconazole started recently and may increase tacrolimus exposure. Urgent dose review recommended.', '2026-04-19 11:25+00', 'current'),
  ('NOTE-0020-A', (select id from ehr_patients where patient_code='EHR-PT-0020'), (select id from ehr_encounters where encounter_code='ENC-0020-A'), 'Primary care medication reconciliation note', 'Poor glycaemic control with neuropathic symptoms and fatty liver. Review hypoglycaemia risk with sulfonylurea therapy and avoid hepatotoxic medicines where possible.', '2026-04-20 13:00+00', 'current')
